"use strict";
function ri(a,b){return a+Math.floor(Math.random()*(b-a+1));}
function pick(a){return a[Math.floor(Math.random()*a.length)];}
function shuffle(a){for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function gcd(a,b){a=Math.abs(a);b=Math.abs(b);while(b){var t=b;b=a%b;a=t;}return a;}
function fmt(n){return String(Number(n.toFixed(6))).replace("-","−");}
function frac(n,d){var g=gcd(n,d);n/=g;d/=g;return d===1?String(n):n+"/"+d;}
function mc(q,a,wrong,why){
  var seen={},opts=[];[a].concat(wrong).forEach(function(o){o=String(o);if(!seen[o]&&opts.length<4){seen[o]=1;opts.push(o);}});
  return {q:q,a:String(a),opts:shuffle(opts),why:why};
}
function numQ(q,ans,why,min){
  var set={},opts=[ans];set[ans]=1;var spread=Math.max(3,Math.round(Math.abs(ans)*0.15)),guard=0;
  while(opts.length<4&&guard<300){guard++;var d=ans+ri(-spread,spread);if(min!=null&&d<min)continue;if(!set[d]){set[d]=1;opts.push(d);}}
  return {q:q,a:fmt(ans),opts:shuffle(opts.map(fmt)),why:why};
}
function pm(n){return n<0?"− "+(-n):"+ "+n;}
function cx(m){return m===1?"x":m===-1?"−x":fmt(m)+"x";}
function neg(n){return n<0?"("+fmt(n)+")":fmt(n);}

