function others(pool,ans,n){var o=shuffle(pool.filter(function(x){return x!==ans;}));var seen={},out=[];o.forEach(function(x){if(!seen[x]&&out.length<n){seen[x]=1;out.push(x);}});return out;}
/* each fact row becomes a question; wrong answers come from the same list */
function fromList(subj,grades,lv,t,rows,makeQ,pool){
  var p=pool||rows.map(function(r){return r[1];});
  rows.forEach(function(r){var q=makeQ(r),w=others(p,r[1],3);if(w.length<3)return;
    B.push({s:subj,g:grades,lv:typeof lv==="function"?lv(r):lv,t:t,q:q.q,a:r[1],w:w,why:q.why});});
}
