/* other ways to ask about the same dated events: year, century, and which came last */
function ordinal(n){return n+(n%100>=11&&n%100<=13?"th":["th","st","nd","rd"][n%10]||"th");}
function eventForms(grades,t,ev){
  var tf=function(e){return typeof t==="function"?e[2]:t;};
  ev.forEach(function(e,k){
    var lv=k%3+1,spread=lv===1?[-60,-30,30,60,90]:lv===2?[-20,-10,10,20,15]:[-6,-3,3,6,2],w=[];
    shuffle(spread).forEach(function(d){var y=String(e[0]+d);if(w.length<3&&w.indexOf(y)<0)w.push(y);});
    B.push({s:"ss",g:grades,lv:lv,fam:"year",t:tf(e),q:"In what year did "+e[1]+" happen?",a:String(e[0]),w:w,why:cap(e[1])+" happened in "+e[0]+"."});
    var c=Math.floor((e[0]-1)/100)+1,cw=[c-2,c-1,c+1].map(function(x){return "The "+ordinal(x)+" century";});
    B.push({s:"ss",g:grades,lv:1,fam:"century",t:tf(e),q:"In which century did "+e[1]+" happen?",a:"The "+ordinal(c)+" century",w:cw,why:e[0]+" is in the "+ordinal(c)+" century (the "+(c-1)+"00s)."});
  });
  var sorted=ev.slice().sort(function(a,b){return a[0]-b[0];});
  for(var k=0;k+4<sorted.length;k+=2){
    var tri=[sorted[k],sorted[k+2],sorted[k+4]],last=tri[2];if(tri[0][0]===tri[1][0]||tri[1][0]===tri[2][0])continue;
    var gap=last[0]-tri[1][0],lv=gap>=50?1:gap>=12?2:3;
    B.push({s:"ss",g:grades,lv:lv,fam:"order",t:tf(last),q:"Which of these happened last? "+shuffle(tri.map(function(e){return cap(e[1]);})).join("; ")+".",a:cap(last[1]),w:[cap(tri[0][1]),cap(tri[1][1]),"They all happened in the same year"],why:"In order: "+tri.map(function(e){return cap(e[1])+" ("+e[0]+")";}).join(", ")+"."});
  }
  GEN.push({s:"ss",g:grades,lv:3,t:typeof t==="function"?ev[0][2]:t,fam:"apart",f:function(){
    var a=pick(ev),b=pick(ev);for(var n=0;n<30&&a[0]===b[0];n++)b=pick(ev);if(a[0]>b[0]){var x=a;a=b;b=x;}var d=b[0]-a[0];
    return {q:"How many years passed between "+a[1]+" ("+a[0]+") and "+b[1]+" ("+b[0]+")?",a:String(d),w:[String(d+10),String(Math.max(1,d-10)),String(d+1)],why:b[0]+" − "+a[0]+" = "+d+" years."};}});
}
/* timelines: "Which happened first?" pairs from dated events */
function timeline(grades,t,ev){
  eventForms(grades,t,ev);
  var pairs=[];for(var i0=0;i0<ev.length;i0++)for(var j0=i0+1;j0<ev.length;j0++)pairs.push([i0,j0]);
  /* keep a spread-out sample of pairs (every third) so "Which happened first?" can't crowd out other questions */
  pairs=pairs.filter(function(p,k){return k%4===0;});
  for(var pi=0;pi<pairs.length;pi++){var i=pairs[pi][0],j=pairs[pi][1];
    var a=ev[i],b=ev[j];if(a[0]===b[0])continue;var gap=Math.abs(a[0]-b[0]),first=a[0]<b[0]?a:b,second=a[0]<b[0]?b:a;
    var lv=gap>=50?1:gap>=12?2:3;
    var flip=(i*7+j*3)%2===0;
    B.push({s:"ss",g:grades,lv:lv,fam:"order",t:typeof t==="function"?t(first,second):t,q:"Which happened first: "+(flip?a[1]+" or "+b[1]:b[1]+" or "+a[1])+"?",a:cap(first[1]),w:[cap(second[1]),"They happened in the same year","Neither one happened"],why:cap(first[1])+" ("+first[0]+") came before "+second[1]+" ("+second[0]+")."});
  }
}
